import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.logging.Logger;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = (String) req.getSession().getAttribute("userId");

        if (userId == null) {
            resp.sendError(401);
            return;
        }

        // Validate reportType against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate dateRange format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query - sortCol is used for ORDER BY
        String query = buildReportQuery(reportType, dateRange, sortCol, userId);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Note: using Statement for dynamic ORDER BY since PreparedStatement
            // doesn't support parameterized ORDER BY clauses
            try (java.sql.Statement stmt = conn.createStatement()) {
                ResultSet rs = stmt.executeQuery(query);
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.printf("  {\"id\": %d, \"title\": \"%s\", \"value\": \"%s\", \"created\": \"%s\"}",
                        rs.getInt("id"),
                        escapeJson(rs.getString("title")),
                        escapeJson(rs.getString("value")),
                        rs.getString("created_at"));
                    first = false;
                }
                out.print("\n]");
            }
        } catch (Exception e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildReportQuery(String reportType, String dateRange, String sortCol, String userId) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, title, value, created_at FROM reports_").append(reportType);
        sb.append(" WHERE owner_id = '").append(userId).append("'");

        if (dateRange != null) {
            String[] parts = dateRange.split("_");
            sb.append(" AND created_at BETWEEN '").append(parts[0]).append("' AND '").append(parts[1]).append("'");
        }

        // Dynamic ORDER BY - sortCol comes from user input
        if (sortCol != null && !sortCol.isEmpty()) {
            sb.append(" ORDER BY ").append(sortCol);
        } else {
            sb.append(" ORDER BY created_at DESC");
        }

        sb.append(" LIMIT 100");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.equals("sales") || type.equals("inventory") || type.equals("audit") || type.equals("finance");
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
